INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Autorisierung dasselbe wie Authentifizierung?', 2, '[{"text": "Nein", "correct": true, "because": "Autorisierung regelt Berechtigungen, Authentifizierung die Identität"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Prozesse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Autorisierung?', 3, '[{"text": "Zugriffsrechte kontrollieren", "correct": true, "because": "Legt fest, was ein Nutzer tun darf"}, {"text": "Identität überprüfen", "correct": false, "because": "Authentifizierung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Anderer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Autorisierung?', 5, '[{"text": "Rollen", "correct": true, "because": "Definieren Zugriffsstufen"}, {"text": "Berechtigungen", "correct": true, "because": "Legen Zugriff fest"}, {"text": "Passwörter", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Autorisierung erfolgt nach Authentifizierung. b) Sie ist optional in Systemen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Autorisierung essenziell für Sicherheit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Autorisierung?', 4, '[{"text": "Rollenzuweisung", "correct": false, "because": "Kern der Autorisierung"}, {"text": "Berechtigungsstufen", "correct": false, "because": "Entscheidend"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Autorisierung vor der Authentifizierung stattfindet?', 2, '[{"text": "Nein", "correct": true, "because": "Erst Identität, dann Rechte"}, {"text": "Ja", "correct": false, "because": "Falsche Reihenfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist typisch für Autorisierung?', 3, '[{"text": "Rollenbasierte Zugriffskontrolle", "correct": true, "because": "RBAC häufig genutzt"}, {"text": "Passwortabfrage", "correct": false, "because": "Authentifizierung"}, {"text": "Biometrische Überprüfung", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Autorisierung?', 5, '[{"text": "Rollenzuweisung", "correct": true, "because": "Definiert Berechtigungen"}, {"text": "Rechteverwaltung", "correct": true, "because": "Kontrolliert Zugriff"}, {"text": "Passwortgenerierung", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Autorisierung schützt vor unbefugtem Zugriff. b) Sie ist ohne Authentifizierung möglich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Authentifizierung Voraussetzung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Autorisierung unwichtig?', 4, '[{"text": "Zugriffsrechte", "correct": false, "because": "Kern der Autorisierung"}, {"text": "Rollen", "correct": false, "because": "Strukturieren Zugriff"}, {"text": "Bürodesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kommt Autorisierung vor der Authentifizierung?', 2, '[{"text": "Nein", "correct": true, "because": "Folgt der Identitätsprüfung"}, {"text": "Ja", "correct": false, "because": "Falsche Reihenfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Autorisierung?', 4, '[{"text": "Sicherheitskontrolle", "correct": true, "because": "Schützt Ressourcen"}, {"text": "Differenzierter Zugriff", "correct": true, "because": "Rollenbasiert"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Autorisierung nur für große Systeme relevant ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in kleinen Systemen nötig"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Autorisierung?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Schützt vor unbefugtem Zugriff"}, {"text": "Schnelligkeit", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Autorisierung verwendet Rollen. b) Sie überprüft die Identität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Identität ist Authentifizierung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine fehlende Autorisierung?', 5, '[{"text": "Unbefugter Zugriff", "correct": true, "because": "Keine Rechteprüfung"}, {"text": "Sicherheitsrisiken", "correct": true, "because": "Daten gefährdet"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Autorisierung unwichtig?', 3, '[{"text": "Rollenverwaltung", "correct": false, "because": "Kernbestandteil"}, {"text": "Zugriffsregeln", "correct": false, "because": "Definiert Berechtigungen"}, {"text": "Farbcodierung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Autorisierung ohne Authentifizierung funktionieren?', 3, '[{"text": "Nein", "correct": true, "because": "Identität muss zuerst geprüft werden"}, {"text": "Ja", "correct": false, "because": "Voraussetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Autorisierung dynamisch sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "Rollen können angepasst werden"}, {"text": "Nein", "correct": false, "because": "Flexibel möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für Autorisierung?', 4, '[{"text": "RBAC", "correct": true, "because": "Rollenbasierte Zugriffskontrolle"}, {"text": "Passwortabfrage", "correct": false, "because": "Authentifizierung"}, {"text": "Biometrie", "correct": false, "because": "Authentifizierung"}]');
